import { path } from '@servicenow/sdk-build-core'
import type { Project } from '../../../src/project'
import * as fs from 'fs'
import { XMLParser } from 'fast-xml-parser'
import { loadTestFile } from './test-utils'
import { createTestContext } from '../../test-utils'

describe('Transform handling of delete_multiple in Flow XML', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    test('Delete entire sys_hub_flow', async () => {
        const project = ctx.createProject()
        const transformedXMLpath = path.resolve(__dirname, 'delete', 'xmls', 'delete_flow.xml')

        project.addFile(path.resolve(__dirname, 'delete', 'hello-world-flow.now.ts'))
        project.registerExplicitId('sys_hub_flow', 'hello_world_log_message_flow', '67528808e7054127a5530fdd7c3ef1d0')

        const result = await project.transform(transformedXMLpath)

        expect(result.changedFiles.length).toBe(1)

        const content = result.changedFiles[0].getContent()
        expect(content).toBe('')
    })
    test('Flow with delete multiple does not remove any non-deleted metadata', async () => {
        const project = ctx.createProject()
        const transformedXMLpath = path.resolve(__dirname, 'delete', 'xmls', 'flow.xml')

        const flowPath = path.resolve(__dirname, 'delete', 'hello-world-flow.now.ts')
        project.addFile(flowPath)
        project.registerExplicitId('sys_hub_flow', 'hello_world_log_message_flow', '6c3c6edfa7a6423fa805dc7d7457c6b2')
        project.registerExplicitId(
            'sys_hub_trigger_instance_v2',
            'hello_world_log_message_flow_trigger',
            '182fbc4cc0d84883aa059f88fb266e84'
        )
        project.registerExplicitId(
            'sys_hub_action_instance_v2',
            'hello_world_log_message_flow_action',
            '95480ff1b9cc4012956ea32c413b4b9b'
        )
        const result = await project.transform(transformedXMLpath)

        expect(result.changedFiles.length).toBe(1)
        const flowPathResult = path.resolve(__dirname, 'delete', 'results', 'hello-world-flow-no-delete.now.ts')

        const expectedContent = fs.readFileSync(flowPathResult, 'utf-8')
        expect(result.changedFiles[0].getContent()).toBe(expectedContent)
    })

    test('Flow with delete multiple does not remove any non-deleted metadata from non-transformed file', async () => {
        const project = ctx.createProject()
        const transformedXMLpath = path.resolve(__dirname, 'delete', 'xmls', 'flow.xml')

        const flowPath = path.resolve(__dirname, 'delete', 'hello-world-flow.now.ts')
        const flowPathUnmodified = path.resolve(__dirname, 'delete', 'hello-world-flow-2.now.ts')
        project.addFile(flowPath)
        project.addFile(flowPathUnmodified)
        project.registerExplicitId('sys_hub_flow', 'hello_world_log_message_flow', '6c3c6edfa7a6423fa805dc7d7457c6b2')
        project.registerExplicitId('sys_hub_flow', 'hello_world_log_message_flow_2', '6c3c6edfa7a6423fa805dc7d7457cccc')

        project.registerExplicitId(
            'sys_hub_trigger_instance_v2',
            'hello_world_log_message_flow_trigger',
            '182fbc4cc0d84883aa059f88fb266999'
        )
        project.registerExplicitId(
            'sys_hub_action_instance_v2',
            'hello_world_log_message_flow_action',
            '95480ff1b9cc4012956ea32c413b4444'
        )
        const result = await project.transform(transformedXMLpath)

        expect(result.changedFiles.length).toBe(1)
        const flowPathResult = path.resolve(__dirname, 'delete', 'hello-world-flow-2.now.ts')

        const expectedContent = fs.readFileSync(flowPathResult, 'utf-8')
        const resultFile = project.getFiles().find((file) => file.getName().includes('hello-world-flow-2'))
        expect(resultFile.getContent()).toBe(expectedContent)
    })
    test('delete multiple removes trigger', async () => {
        const project = ctx.createProject()
        const transformedXMLpath = path.resolve(__dirname, 'delete', 'xmls', 'delete_trigger.xml')

        project.addFile(path.resolve(__dirname, 'delete', 'hello-world-flow.now.ts'))
        project.registerExplicitId('sys_hub_flow', 'hello_world_log_message_flow', '97e4682fc8793250f877b60957826e0b')
        project.registerExplicitId(
            'sys_hub_trigger_instance_v2',
            'hello_world_log_message_flow_trigger',
            '182fbc4cc0d84883aa059f88fb266e84'
        )
        project.registerExplicitId(
            'sys_hub_action_instance_v2',
            'hello_world_log_message_flow_action',
            '95480ff1b9cc4012956ea32c413b4b9b'
        )

        const result = await project.transform(transformedXMLpath)

        const flowPathResult = path.resolve(__dirname, 'delete', 'results', 'hello-world-flow-delete-trigger.now.ts')
        const expectedContent = fs.readFileSync(flowPathResult, 'utf-8')
        expect(result.changedFiles.length).toBe(1)
        expect(result.changedFiles[0].getContent()).toBe(expectedContent)
    })

    test('delete multiple removes action', async () => {
        const project = ctx.createProject()
        const transformedXMLpath = path.resolve(__dirname, 'delete', 'xmls', 'delete_action.xml')

        project.addFile(path.resolve(__dirname, 'delete', 'hello-world-flow.now.ts'))
        project.registerExplicitId('sys_hub_flow', 'hello_world_log_message_flow', 'a9e4e42fc8793250f877b60957826e68')
        project.registerExplicitId(
            'sys_hub_trigger_instance_v2',
            'hello_world_log_message_flow_trigger',
            '182fbc4cc0d84883aa059f88fb266e84'
        )

        const result = await project.transform(transformedXMLpath)

        const flowPathResult = path.resolve(__dirname, 'delete', 'results', 'hello-world-flow-delete-action.now.ts')
        const expectedContent = fs.readFileSync(flowPathResult, 'utf-8')
        expect(result.changedFiles.length).toBe(1)
        expect(result.changedFiles[0].getContent()).toBe(expectedContent)
    })
})

/**
 * Test suite for delete_multiple XML generation in flow-to-xml.ts
 *
 * Tests verify that delete_multiple entries are generated correctly for descendant tables
 * based on the relationships configured in flow-definition-plugin.ts.
 *
 * Tables excluded from delete_multiple generation (EXCLUDED_TABLES in flow-to-xml.ts):
 * - sys_flow_record_trigger
 * - sys_flow_timer_trigger
 * - sys_hub_flow_snapshot
 * - sys_choice
 * - sys_documentation
 * - sys_complex_object
 * - sys_element_mapping
 */

interface DeleteMultipleEntry {
    '@_action': string
    '@_query': string
}

/**
 * Helper to extract delete_multiple entries from parsed XML
 */
// biome-ignore lint/suspicious/noExplicitAny: XML parsing returns unknown structure
function getDeleteMultipleEntries(parsedXml: any, tableName: string): DeleteMultipleEntry[] {
    const tableData = parsedXml.record_update?.[tableName]
    if (!tableData) {
        return []
    }

    const entries = Array.isArray(tableData) ? tableData : [tableData]
    // biome-ignore lint/suspicious/noExplicitAny: XML parsing returns unknown structure
    return entries.filter((entry: any) => entry['@_action'] === 'delete_multiple')
}

/**
 * Helper to get all delete_multiple table names from XML
 */
// biome-ignore lint/suspicious/noExplicitAny: XML parsing returns unknown structure
function getAllDeleteMultipleTables(parsedXml: any): string[] {
    const tables: string[] = []
    const recordUpdate = parsedXml.record_update
    if (!recordUpdate) {
        return tables
    }

    for (const [tableName, tableData] of Object.entries(recordUpdate)) {
        if (tableName.startsWith('@_') || tableName === '#text') {
            continue
        }
        const entries = Array.isArray(tableData) ? tableData : [tableData]
        // biome-ignore lint/suspicious/noExplicitAny: XML parsing returns unknown structure
        const hasDeleteMultiple = entries.some((entry: any) => entry['@_action'] === 'delete_multiple')
        if (hasDeleteMultiple) {
            tables.push(tableName)
        }
    }
    return tables
}

/**
 * Helper to get XML output for a flow file
 */
async function getFlowXmlOutput(project: Project, fileName: string) {
    const fileContent = loadTestFile(fileName, 'create')
    project.addFile({ path: fileName, content: fileContent })
    const file = project.getFile(fileName)
    if (!file) {
        throw new Error(`File ${fileName} not found in project`)
    }
    const output = await file.getOutput()
    const parser = new XMLParser({ ignoreAttributes: false })

    // Find the flow XML file (not action or other files)
    const flowXmlFile = output.find((f) => f.path.includes('sys_hub_flow_'))
    if (!flowXmlFile) {
        throw new Error(`No sys_hub_flow XML file found in output for ${fileName}`)
    }

    return {
        parsed: parser.parse(flowXmlFile.content),
        content: flowXmlFile.content,
        allFiles: output.map((f) => ({ path: f.path, parsed: parser.parse(f.content) })),
    }
}

describe('Flow delete_multiple XML generation', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())

    describe('Direct flow descendant tables', () => {
        test('generates delete_multiple for sys_hub_trigger_instance_v2', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-simple.now.ts')

            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_hub_trigger_instance_v2')
            expect(deleteEntries.length).toBeGreaterThanOrEqual(1)

            // Verify query format: flow=<flowId>^sys_idNOT IN<recordIds>
            const firstEntry = deleteEntries[0]
            expect(firstEntry['@_query']).toMatch(/^flow=/)
        })

        test('generates delete_multiple for sys_hub_action_instance_v2', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-action.now.ts')

            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_hub_action_instance_v2')
            expect(deleteEntries.length).toBeGreaterThanOrEqual(1)

            // Verify query format
            const firstEntry = deleteEntries[0]
            expect(firstEntry['@_query']).toMatch(/^flow=/)
        })

        test.skip('generates delete_multiple for sys_hub_sub_flow_instance_v2', async () => {
            const project = ctx.createProject()
            const { allFiles } = await getFlowXmlOutput(project, 'flow-def-with-subflows.now.ts')

            // Find the main flow (type=flow) which contains subflow instances
            // Subflows won't have sys_hub_sub_flow_instance_v2 - only main flows do
            const mainFlowXml = allFiles.find(
                (f) => f.path.includes('sys_hub_flow_') && f.parsed.record_update?.sys_hub_sub_flow_instance_v2
            )

            if (mainFlowXml) {
                const deleteEntries = getDeleteMultipleEntries(mainFlowXml.parsed, 'sys_hub_sub_flow_instance_v2')
                expect(deleteEntries.length).toBeGreaterThanOrEqual(1)

                // Verify query format
                const firstEntry = deleteEntries[0]
                expect(firstEntry['@_query']).toMatch(/^flow=/)
            }
        })

        test('generates delete_multiple for sys_hub_flow_stage when present', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-simple.now.ts')

            // sys_hub_flow_stage may or may not be present depending on the flow
            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_hub_flow_stage')
            if (deleteEntries.length > 0) {
                const firstEntry = deleteEntries[0]
                expect(firstEntry['@_query']).toMatch(/^flow=/)
            }
        })
    })

    describe('Input/Output/Variable descendant tables', () => {
        test.skip('generates delete_multiple for sys_hub_flow_input when subflow has inputs', async () => {
            const project = ctx.createProject()
            // Use a subflow file that has inputs defined
            const { allFiles } = await getFlowXmlOutput(project, 'flow-def-with-subflows.now.ts')

            // Find subflow XML (type=subflow)
            const subflowXml = allFiles.find(
                (f) => f.path.includes('sys_hub_flow_') && f.parsed.record_update?.sys_hub_flow_input
            )

            if (subflowXml) {
                const deleteEntries = getDeleteMultipleEntries(subflowXml.parsed, 'sys_hub_flow_input')
                expect(deleteEntries.length).toBeGreaterThanOrEqual(1)

                // Verify query format: model=<flowId>^sys_idNOT IN<recordIds>
                const firstEntry = deleteEntries[0]
                expect(firstEntry['@_query']).toMatch(/^model=/)
            }
        })

        test.skip('generates delete_multiple for sys_hub_flow_output when subflow has outputs', async () => {
            const project = ctx.createProject()
            const { allFiles } = await getFlowXmlOutput(project, 'flow-def-with-subflows.now.ts')

            // Find subflow XML that has outputs
            const subflowXml = allFiles.find(
                (f) => f.path.includes('sys_hub_flow_') && f.parsed.record_update?.sys_hub_flow_output
            )

            if (subflowXml) {
                const deleteEntries = getDeleteMultipleEntries(subflowXml.parsed, 'sys_hub_flow_output')
                expect(deleteEntries.length).toBeGreaterThanOrEqual(1)

                // Verify query format
                const firstEntry = deleteEntries[0]
                expect(firstEntry['@_query']).toMatch(/^model=/)
            }
        })

        test('generates delete_multiple for sys_hub_flow_variable when flow has variables', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-variables.now.ts')

            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_hub_flow_variable')
            expect(deleteEntries.length).toBeGreaterThanOrEqual(1)

            // Verify query format
            const firstEntry = deleteEntries[0]
            expect(firstEntry['@_query']).toMatch(/^model=/)
        })
    })

    describe('Cascading delete_multiple (sys_hub_alias_mapping)', () => {
        test('generates cascading delete_multiple for sys_hub_alias_mapping per action instance', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-action.now.ts')

            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_hub_alias_mapping')

            // Cascading delete generates one delete_multiple per action instance
            // Query format: source_id=<instanceId>
            if (deleteEntries.length > 0) {
                deleteEntries.forEach((entry) => {
                    expect(entry['@_query']).toMatch(/^source_id=/)
                })
            }
        })

        test.skip('generates cascading delete_multiple for sys_hub_alias_mapping per subflow instance', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-subflows.now.ts')

            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_hub_alias_mapping')

            // Cascading delete generates one delete_multiple per subflow instance
            if (deleteEntries.length > 0) {
                deleteEntries.forEach((entry) => {
                    expect(entry['@_query']).toMatch(/^source_id=/)
                })
            }
        })
    })

    describe('Query format validation', () => {
        test('delete_multiple query includes sys_idNOT IN when records exist', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-action.now.ts')

            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_hub_action_instance_v2')
            expect(deleteEntries.length).toBeGreaterThanOrEqual(1)

            // When records exist, query should include sys_idNOT IN to preserve them
            const firstEntry = deleteEntries[0]
            expect(firstEntry['@_query']).toContain('sys_idNOT IN')
        })

        test('delete_multiple query has correct flow reference field', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-simple.now.ts')

            // Verify trigger instance uses 'flow' field
            const triggerEntries = getDeleteMultipleEntries(parsed, 'sys_hub_trigger_instance_v2')
            if (triggerEntries.length > 0) {
                expect(triggerEntries[0]['@_query']).toMatch(/^flow=/)
            }
        })
    })

    describe('Excluded tables validation', () => {
        test('does NOT generate delete_multiple for sys_choice (excluded)', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-variables.now.ts')

            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_choice')
            // sys_choice is in EXCLUDED_TABLES, so no delete_multiple should be generated
            expect(deleteEntries.length).toBe(0)
        })

        test('does NOT generate delete_multiple for sys_documentation (excluded)', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-variables.now.ts')

            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_documentation')
            // sys_documentation is in EXCLUDED_TABLES
            expect(deleteEntries.length).toBe(0)
        })

        test('does NOT generate delete_multiple for sys_complex_object (excluded)', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-variables.now.ts')

            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_complex_object')
            // sys_complex_object is in EXCLUDED_TABLES
            expect(deleteEntries.length).toBe(0)
        })
    })

    describe('Variable value tables', () => {
        test('generates delete_multiple for sys_variable_value when present', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-object-action.now.ts')

            const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_variable_value')

            // sys_variable_value should have delete_multiple if present
            if (deleteEntries.length > 0) {
                const firstEntry = deleteEntries[0]
                expect(firstEntry['@_query']).toMatch(/^document_key=/)
            }
        })
    })

    describe('Comprehensive table coverage', () => {
        test('all configured descendant tables have proper delete_multiple handling', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-action.now.ts')

            const deleteMultipleTables = getAllDeleteMultipleTables(parsed)

            // Verify that tables with delete_multiple have proper query format
            for (const tableName of deleteMultipleTables) {
                const entries = getDeleteMultipleEntries(parsed, tableName)
                entries.forEach((entry) => {
                    // All delete_multiple entries should have a query
                    expect(entry['@_query']).toBeDefined()
                    expect(entry['@_query'].length).toBeGreaterThan(0)

                    // Query should have format: field=value or field=value^sys_idNOT IN<ids>
                    expect(entry['@_query']).toMatch(/^[a-z_]+=/)
                })
            }
        })

        test.skip('flow with multiple instances generates correct number of delete_multiple entries', async () => {
            const project = ctx.createProject()
            const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-subflows.now.ts')

            // For subflow instances, there should be cascading alias_mapping deletes
            const aliasEntries = getDeleteMultipleEntries(parsed, 'sys_hub_alias_mapping')

            // Each subflow instance should have its own alias_mapping delete_multiple
            // flow-def-with-subflows.now.ts has 2 subflow instances
            // So we expect at least 2 alias_mapping delete_multiple entries
            if (aliasEntries.length > 0) {
                expect(aliasEntries.length).toBeGreaterThanOrEqual(2)
            }
        })
    })

    describe('Nested relationship tables', () => {
        test('generates delete_multiple for sys_hub_flow_logic_instance_v2 when flow has logic', async () => {
            // Test with a flow that has flow logic (if/else, forEach, etc.)
            const project = ctx.createProject()

            try {
                // Try to load a flow with logic constructs
                const { parsed } = await getFlowXmlOutput(project, 'flow-def-with-action.now.ts')

                const deleteEntries = getDeleteMultipleEntries(parsed, 'sys_hub_flow_logic_instance_v2')

                // If flow logic is present, verify delete_multiple format
                if (deleteEntries.length > 0) {
                    const firstEntry = deleteEntries[0]
                    expect(firstEntry['@_query']).toMatch(/^flow=/)
                }
            } catch {
                // Skip if file doesn't exist
            }
        })
    })
})
